1	import { describe, test, expect } from 'vitest';
2	import { buildDisImageSrc, resolveDisImageSrc } from './buildDisImageSrc';
3	
4	describe('buildDisImageSrc', () => {
5	  test('appends a DIS query template with the default quality when the URL has no existing query string', () => {
6	    expect(buildDisImageSrc('https://example.test/image.jpg')).toBe('https://example.test/image.jpg[?sw={width}&q=80]');
7	  });
8	
9	  test('uses & instead of ? when the URL already has a query string', () => {
10	    expect(buildDisImageSrc('https://example.test/image.jpg?foo=bar')).toBe(
11	      'https://example.test/image.jpg?foo=bar[&sw={width}&q=80]',
12	    );
13	  });
14	
15	  test('accepts a custom quality', () => {
16	    expect(buildDisImageSrc('https://example.test/image.jpg', 60)).toBe(
17	      'https://example.test/image.jpg[?sw={width}&q=60]',
18	    );
19	  });
20	
21	  test('returns a data: URL unchanged — DIS resizing is meaningless for a URL that already is the image bytes', () => {
22	    const dataUrl = 'data:image/svg+xml;base64,PHN2Zz48L3N2Zz4=';
23	    expect(buildDisImageSrc(dataUrl)).toBe(dataUrl);
24	  });
25	
26	  test('returns a blob: URL unchanged', () => {
27	    const blobUrl = 'blob:https://example.test/1234-5678';
28	    expect(buildDisImageSrc(blobUrl)).toBe(blobUrl);
29	  });
30	});
31	
32	describe('resolveDisImageSrc', () => {
33	  test('substitutes the {width} placeholder and strips the [...] wrapper', () => {
34	    expect(resolveDisImageSrc('https://example.test/image.jpg[?sw={width}&q=80]', 204)).toBe(
35	      'https://example.test/image.jpg?sw=204&q=80',
36	    );
37	  });
38	
39	  test('round-trips with buildDisImageSrc', () => {
40	    const templated = buildDisImageSrc('https://example.test/image.jpg', 67);
41	    expect(resolveDisImageSrc(templated, 204)).toBe('https://example.test/image.jpg?sw=204&q=67');
42	  });
43	});
