1	import { useEffect, useRef, useState } from 'react';
2	
3	type UseZimmModalParams = {
4	  /** Whether the dialog is currently open. */
5	  isOpen: boolean;
6	  /** Called when the dialog should close. Unused now that Chakra's Modal owns Escape/overlay-
7	   *  click handling directly, but kept in the param type so existing call sites need no change. */
8	  onClose: () => void;
9	};
10	
11	type UseZimmModalReturn = {
12	  /** False until after the first client render, so the dialog is not rendered during SSR. */
13	  mounted: boolean;
14	  /** Attach to the element that bounds the dialog's own content — kept for existing markup
15	   *  compatibility. Chakra's Modal now traps focus across the whole ModalContent itself, so this
16	   *  ref is no longer load-bearing. */
17	  trapRef: React.RefObject<HTMLElement>;
18	  /** Attach to the wrapper around the first field — kept for existing markup compatibility.
19	   *  Chakra's Modal now auto-focuses the first focusable element on open by default. */
20	  firstFocusRef: React.RefObject<HTMLDivElement>;
21	};
22	
23	/**
24	 * Mount gating for the dialog. Focus trap, initial focus, focus restore, body-scroll lock, and
25	 * Escape/overlay-click-to-close all moved onto Chakra's Modal primitive when ZimmModal was
26	 * rebuilt on it — this hook now only tracks first-client-render so ZimmModal doesn't render
27	 * before hydration. Still returns trapRef/firstFocusRef so ZimmSubscribeModal's existing markup
28	 * needs no changes; neither ref drives behaviour any more.
29	 *
30	 * @param params isOpen and the close callback — unused by this hook now (see UseZimmModalParams),
31	 *   kept only so the call-site's object literal still type-checks against the same shape.
32	 * @returns the mount flag plus the two (now inert) refs the dialog markup still attaches
33	 */
34	// eslint-disable-next-line @typescript-eslint/no-unused-vars -- signature kept for call-site compatibility, see JSDoc above
35	export const useZimmModal = (_params: UseZimmModalParams): UseZimmModalReturn => {
36	  const [mounted, setMounted] = useState(false);
37	  const trapRef = useRef<HTMLElement>(null);
38	  const firstFocusRef = useRef<HTMLDivElement>(null);
39	
40	  useEffect(() => {
41	    setMounted(true);
42	  }, []);
43	
44	  return { mounted, trapRef, firstFocusRef };
45	};
